import{_ as t,o,c as a,a2 as s}from"./chunks/framework.TaNiW7i8.js";const p=JSON.parse('{"title":"Introduction","description":"","frontmatter":{"title":"Introduction"},"headers":[],"relativePath":"en/guide/index.md","filePath":"en/guide/index.md"}'),n={name:"en/guide/index.md"};function i(r,e,h,d,l,c){return o(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h1><p>Kessho is a desktop application that keeps a <strong>structured memory</strong> for your AI agents: a folder of Markdown files that belongs to you. A simple, flat memory, where notes just pile up, grows out of control; Kessho&#39;s is organised into zones, projects and domains, with summaries and archives, so that its growth stays under control. Your AI agents read it and add to it; the application shows it to you, keeps it tidy and lets you edit it. This guide walks through the application, screen by screen.</p><p>The screenshots in this guide show a fictitious demonstration memory.</p><h2 id="the-ideas-to-know" tabindex="-1">The ideas to know <a class="header-anchor" href="#the-ideas-to-know" aria-label="Permalink to &quot;The ideas to know&quot;">​</a></h2><p><strong>The memory.</strong> It is a plain folder on your disk. It is portable: you can copy it, back it up, open it with other tools. It works with Obsidian, without depending on it.</p><p><strong>Notes.</strong> Each note is a Markdown file. Kessho files notes in <strong>zones</strong>, which say what a note is for: a session, a piece of knowledge, a procedure, a principle, a goal, a person… See <a href="/Kessho/en/guide/zones.html">Zones</a>.</p><p><strong>Projects and domains.</strong> A note belongs to a project; projects can be grouped under a domain. Each carries a summary you can hand to an agent so it picks the work back up: these are the context keys (see <a href="/Kessho/en/guide/home.html">Home</a>).</p><p><strong>Agents.</strong> Your AI assistant talks to the memory through an MCP server, <code>kessho-mcp</code>, shipped with the application. Kessho declares it to the assistants installed on your machine (see <a href="/Kessho/en/guide/agents.html">Connect your agents</a>). What the agent writes shows up in the application; what you change in the application, the agent reads.</p><h2 id="where-to-start" tabindex="-1">Where to start <a class="header-anchor" href="#where-to-start" aria-label="Permalink to &quot;Where to start&quot;">​</a></h2><p><strong>Getting started</strong></p><ol><li><a href="/Kessho/en/guide/first-run.html">First launch</a>: the five-step wizard.</li><li><a href="/Kessho/en/guide/vault.html">Choose your memory</a>: where the folder lives, and how to change it.</li><li><a href="/Kessho/en/guide/agents.html">Connect your agents</a>: declare Kessho to your assistants.</li></ol><p><strong>Screen by screen</strong></p><ul><li><a href="/Kessho/en/guide/home.html">Home</a>: the state of the memory at a glance, and the context keys.</li><li><a href="/Kessho/en/guide/zones.html">Zones</a>: browse, filter and file notes.</li><li><a href="/Kessho/en/guide/atom.html">Atom and editor</a>: read and write a note.</li><li><a href="/Kessho/en/guide/graph.html">Graph</a>: see how notes relate to one another.</li><li><a href="/Kessho/en/guide/sync.html">Sync</a>: back up the memory with git.</li><li><a href="/Kessho/en/guide/settings.html">Settings</a>: appearance, memory, connectors.</li><li><a href="/Kessho/en/guide/help.html">Help</a>: find help inside the application.</li></ul><h2 id="and-with-an-agent" tabindex="-1">And with an agent? <a class="header-anchor" href="#and-with-an-agent" aria-label="Permalink to &quot;And with an agent?&quot;">​</a></h2><p>This guide covers what you do with the mouse and keyboard. For what you ask your agent to do — resume a session, archive, search — see <a href="/Kessho/en/agent/">With an agent</a>. The tools themselves are described in the <a href="/Kessho/en/reference/mcp/">MCP reference</a>.</p>',15)])])}const g=t(n,[["render",i]]);export{p as __pageData,g as default};
